function LoginScreen(){
  const t=useT();
  const [loading,setLoading]=useState(false);const [error,setError]=useState("");
  async function login(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setLoading(true);setError("");const form=new FormData(e.currentTarget);try{const res=await fetch("/api/auth/login",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({sharedId:form.get("sharedId"),password:form.get("password")})});const json=await res.json();if(!res.ok)throw new Error(json.error);location.reload()}catch(err){setError(err instanceof Error?err.message:"เข้าสู่ระบบไม่สำเร็จ");setLoading(false)}}
  return <main className="login-page"><section className="login-art"><div className="eyebrow"><Sparkles size={13}/> private journeys · made together</div><h1>{t("เก็บทุกเส้นทาง")}<br/>{t("ไว้ในที่เดียว")}</h1><p>{t("แพลนที่เที่ยว จดโมเมนต์ และคุมงบ")}<br/>{t("ในสมุดเดินทางของ B & N")}</p><div className="login-route"><span>BKK</span><div><Plane size={20}/></div><span>ANYWHERE</span></div></section><section className="login-panel"><Brand/><div className="login-copy"><span className="mini-kicker">WELCOME BACK</span><h2>{t("เปิดสมุดเดินทาง")}</h2><p>{t("ใช้ Shared Trip ID เดียวกันเพื่อเข้าถึงแพลนของเรา")}</p></div><form className="form-grid" onSubmit={login}><div className="field"><label>SHARED TRIP ID</label><input name="sharedId" autoComplete="username" required/></div><div className="field"><label>{t("รหัสผ่าน")}</label><input name="password" type="password" autoComplete="current-password" required/></div>{error&&<p className="login-error">{t(error)}</p>}<button className="primary-btn" disabled={loading}>{t(loading?"กำลังเปิดสมุดทริป…":"เข้าสู่สมุดเดินทาง")}<ArrowRight size={16}/></button></form><p className="login-hint"><Crown size={12}/>{t("พื้นที่ส่วนตัวสำหรับสมาชิกที่ใช้ Shared ID นี้")}</p></section></main>;
}

function TripCard({trip,past,now,selectTrip,editTrip,deleteTrip}:{trip:Trip;past?:boolean;now:number;selectTrip:(t:Trip)=>void;editTrip:(t:Trip)=>void;deleteTrip:(t:Trip)=>void}){
  const t=useT();
  const coverUrl=trip.cover_image_url||DEFAULT_TRIP_COVER;
  const coverStyle={backgroundImage:`url("${coverUrl}")`};
  const departure=trip.outbound_departure_at?new Date(trip.outbound_departure_at).getTime():null;
  const returnAt=trip.return_departure_at?new Date(trip.return_departure_at).getTime():null;
  const ongoing=departure!==null&&departure<=now&&(returnAt===null||returnAt>=now);
  const countdownLabel=departure===null?t("ยังไม่กำหนดวัน"):ongoing?t("กำลังเดินทาง"):t(`อีก ${Math.max(0,Math.ceil((departure-now)/86400000))} วัน`);
  return <article className={`trip-card ${past?"past":""}`}><button className="trip-card-link" onClick={()=>selectTrip(trip)} aria-label={`${past?"View":"Open"} trip ${trip.name}`}/><div className="trip-cover" style={coverStyle}><span/>{past?<b className="past-badge">{t("ที่ผ่านมาแล้ว")}</b>:<b className={`countdown-badge ${ongoing?"ongoing-badge":"upcoming-badge"}`}>{countdownLabel}</b>}<div className="trip-actions"><button onClick={()=>editTrip(trip)} aria-label={t("แก้ไข")}><Pencil size={15}/></button><button onClick={()=>deleteTrip(trip)} aria-label={t("ลบ")}><Trash2 size={15}/></button></div></div><div className="trip-body"><span className="trip-duration">{tripRangeLabel(trip)}</span><h3>{trip.name}</h3><p><MapPin size={12}/>{trip.destination}</p><div className="trip-meta"><span>{t(`${trip.total_days} วัน`)}</span><span>฿{Number(trip.budget_thb).toLocaleString()}</span></div></div></article>;
}

function Dashboard({trips,selectTrip,createTrip,editTrip,deleteTrip}:{trips:Trip[];selectTrip:(t:Trip)=>void;createTrip:()=>void;editTrip:(t:Trip)=>void;deleteTrip:(t:Trip)=>void}){
  const t=useT();
  const [now]=useState(()=>Date.now());
  const upcoming=trips.filter(t=>!t.return_departure_at||new Date(t.return_departure_at).getTime()>=now);
  const past=trips.filter(t=>t.return_departure_at&&new Date(t.return_departure_at).getTime()<now);
  const cards=(items:Trip[],isPast=false)=><div className="trip-grid">{items.map(t=><TripCard key={t.id} trip={t} past={isPast} now={now} selectTrip={selectTrip} editTrip={editTrip} deleteTrip={deleteTrip}/>)}</div>;
  return <div className="screen"><section className="welcome"><div><span className="eyebrow"><Sparkles size={13}/> OUR TRAVEL JOURNAL</span><h1>{t("เรื่องราวระหว่างทาง")}</h1><p>{t("แพลนทริป หรือกลับมาเปิดดูความทรงจำเดิมได้ทุกเมื่อ")}</p></div><div className="welcome-actions"><button className="primary-btn" onClick={createTrip}><Plus size={17}/>{t("สร้างทริปใหม่")}</button></div></section><div className="section-head"><div><span className="section-kicker">UPCOMING JOURNEYS</span><h2>{t("ทริปที่กำลังจะมาถึง")}</h2><p>{t(`${upcoming.length} ทริปที่รอเราอยู่`)}</p></div></div>{upcoming.length?cards(upcoming):<EmptyState title={t("หน้ากระดาษนี้ยังว่าง")} description={t("สร้างทริปใหม่ แล้วเริ่มเติมสถานที่ที่อยากไปกัน")} action={t("สร้างทริปใหม่")} onClick={createTrip}/>}<div className="section-head past-head"><div><span className="section-kicker pink">PAST JOURNEYS</span><h2>{t("ทริปที่ผ่านมาแล้ว")}</h2><p>{t("ย้อนกลับไปดูเส้นทางและความทรงจำเดิมได้เสมอ")}</p></div><span className="past-count">{past.length}</span></div>{past.length?cards(past,true):<article className="card past-empty">{t("เมื่อจบทริปแล้ว เราจะเก็บการเดินทางไว้ตรงนี้ให้อัตโนมัติ")}</article>}</div>;
}

function TripHeader({trip,back,actions}:{trip:Trip;back:()=>void;actions?:ReactNode}){
  const t=useT();
  const coverUrl=trip.cover_image_url||DEFAULT_TRIP_COVER;
  const coverStyle={backgroundImage:`url("${coverUrl}")`};
  return <div className="trip-detail-head has-cover" style={coverStyle}><button className="back-btn trip-cover-back" onClick={back} aria-label={t("ย้อนกลับ")} title={t("ย้อนกลับ")}><ChevronLeft size={19}/></button>{actions&&<div className="trip-cover-actions">{actions}</div>}<div><span className="eyebrow">{trip.destination}</span><h1 className="page-title">{trip.name}</h1><p className="page-sub">{t(`บิน ${flightLabel(trip.outbound_departure_at)} · กลับ ${flightLabel(trip.return_departure_at)} · ${trip.total_days} วัน`)}</p></div></div>;
}

function TimelineCostBar({item,openCost}:{item:Itinerary;openCost:(item:Itinerary,index?:number)=>void}){
  const costs=item.cost_items||[];
  if(!costs.length)return null;
  return <div className="inline-cost"><div className="timeline-cost-chips">{costs.map((cost,index)=><button type="button" key={cost.id||`${cost.key}-${index}`} onClick={()=>openCost(item,index)}><span>{cost.key}</span><b>{costSourceLabel(cost)}</b></button>)}</div></div>;
}

function TripHub({trip,items,day,setDay,back,editTrip,addPlace,editPlace,openCost}:{trip:Trip;items:Itinerary[];day:number;setDay:(day:number)=>void;back:()=>void;editTrip:()=>void;addPlace:(day:number)=>void;editPlace:(item:Itinerary)=>void;openCost:(item?:Itinerary,index?:number,defaultDay?:number)=>void}){
  const t=useT();
  const [view,setView]=useState<"plan"|"expenses">("plan");
  const now=useMinuteClock();
  const tripDay=tripDayAt(trip,now);
  const currentStopRef=useRef<HTMLDivElement>(null);
  useEffect(()=>setDay(tripDay!==null&&tripDay>trip.total_days?trip.total_days:tripDay!==null&&tripDay>=1?tripDay:1),[trip.id,trip.total_days,tripDay,setDay]);
  const baseDate=localDate(trip.outbound_departure_at,trip.start_date);
  const activeDateLabel=tripDayLabel(baseDate,day);
  const dayItems=items.filter(item=>item.day_number===day).sort((a,b)=>(a.start_time||"99:99").localeCompare(b.start_time||"99:99"));
  const slots={morning:"เช้า",afternoon:"บ่าย",evening:"เย็น"};
  const nowMinutes=now.getHours()*60+now.getMinutes();
  const currentIndex=tripDay===day?dayItems.reduce((found,item,index)=>{const start=timeInMinutes(item.start_time);return start!==null&&start<=nowMinutes?index:found},-1):-1;
  const currentItemId=currentIndex>=0?dayItems[currentIndex].id:null;
  useEffect(()=>{if(!currentItemId||!currentStopRef.current)return;const frame=requestAnimationFrame(()=>currentStopRef.current?.scrollIntoView({behavior:"smooth",block:"center"}));return()=>cancelAnimationFrame(frame)},[currentItemId]);
  return <div className="screen trip-hub-screen">
    <div className="trip-cover-region"><TripHeader trip={trip} back={back} actions={<><button type="button" onClick={editTrip}><Pencil size={18}/><span>แก้ไข</span></button><button type="button" onClick={()=>setView(current=>current==="plan"?"expenses":"plan")}>{view==="plan"?<ReceiptText size={18}/>:<Navigation size={18}/>}<span>{view==="plan"?"ค่าใช้จ่าย":"แพลน"}</span></button></>}/></div>
    <div className="trip-hub-body">
    {view==="plan"?<>
    <div className="day-strip">{Array.from({length:trip.total_days},(_,index)=>index+1).map(number=>{const date=new Date(`${baseDate}T00:00:00`);date.setDate(date.getDate()+number-1);const isToday=tripDay===number;const isPast=tripDay!==null&&tripDay>number;return <button key={number} className={`day-pill ${day===number?"active":""} ${isToday?"today":""} ${isPast?"past-day":""}`} onClick={()=>setDay(number)}><small>DAY</small><strong>{number}</strong><small>{isToday?"วันนี้":date.toLocaleDateString("en",{weekday:"short"})}</small></button>})}</div>
    <div className="section-head timeline-heading"><div><h2>แผนวันที่ {day}<span className="timeline-date-label">· {activeDateLabel}</span></h2><p>{tripDay===day?`เวลาปัจจุบัน ${now.toLocaleTimeString("th-TH",{hour:"2-digit",minute:"2-digit"})} · `:""}{dayItems.length} สถานที่ · เรียงตามเวลาอัตโนมัติ</p></div><button className="add-btn timeline-fab" onClick={()=>addPlace(day)} aria-label={`เพิ่มรายการวันที่ ${day}`}><Plus size={24}/></button></div>
    {dayItems.length===0?<EmptyState title={`Day ${day} ยังว่างอยู่`} description="เพิ่มสถานที่และเวลา รายการใหม่จะถูกเรียงใน Timeline อัตโนมัติ" action="เพิ่มสถานที่" onClick={()=>addPlace(day)}/>:<div className="timeline editable-timeline">{dayItems.map((item,index)=>{
      const isLast=index===dayItems.length-1;
      const isCurrent=index===currentIndex;
      const isPast=tripDay!==null&&(tripDay>day||(tripDay===day&&currentIndex>=0&&index<currentIndex));
      const previous=index>0?dayItems[index-1]:null;
      const origin=previous?.address||previous?.place_name||"";
      const destination=item.address||item.place_name;
      const mode=item.transport_mode?.includes("เดิน")?"walking":item.transport_mode?.includes("รถยนต์")||item.transport_mode?.includes("แท็กซี่")?"driving":"transit";
      const mapsUrl=previous?`https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(origin)}&destination=${encodeURIComponent(destination)}&travelmode=${mode}`:"";
      const currentLocationMapsUrl=`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(destination)}&travelmode=${mode}`;
      return <div ref={isCurrent?currentStopRef:undefined} className={`timeline-stop ${isCurrent?"current-stop":""} ${isPast?"past-stop":""}`} key={item.id}>
        <div className="event"><div className="event-dot"><MapPin size={16}/></div><article className="event-card editable-event-card"><button className="event-card-main" onClick={()=>editPlace(item)}><div className="event-copy"><span className="event-time">{item.start_time?.slice(0,5)||"ไม่ระบุเวลา"} · {slots[item.time_slot]}</span><div className="timeline-title-row"><h3>{item.place_name}</h3></div><p><MapPin size={10}/>{item.address||"ยังไม่ได้ระบุสถานที่"}</p>{item.transport_note&&<p className="event-detail">{item.transport_note}</p>}</div><span className="event-edit"><Pencil size={14}/></span></button><TimelineCostBar item={item} openCost={openCost}/><div className="navigate-actions">{previous&&<a className="navigate-point-btn" href={mapsUrl} target="_blank" rel="noreferrer" aria-label={`นำทางจาก ${previous.place_name} ไป ${item.place_name}`} title="นำทางจากจุดก่อนหน้า"><Navigation size={17}/></a>}<a className="navigate-point-btn navigate-current-btn" href={currentLocationMapsUrl} target="_blank" rel="noreferrer" aria-label={`นำทางจากที่อยู่ปัจจุบันไป ${item.place_name}`} title="นำทางจากที่อยู่ปัจจุบัน"><LocateFixed size={17}/></a><button type="button" className="navigate-point-btn expense-point-btn" onClick={()=>openCost(item)} aria-label={t("กรอกเงิน")} title={t("กรอกเงิน")}><ReceiptText size={16}/></button></div></article></div>
        {!isLast&&<div className="transport"><TrainFront size={12}/><span>{item.transport_mode||"เส้นทางไปจุดถัดไป"}{item.transport_note?` · ${item.transport_note}`:""}</span></div>}
      </div>
    })}</div>}</>:<PlanExpensesContent trip={trip} items={items} openCost={openCost}/>}
    </div>
  </div>;
}

function TimelineScreen({trip,items,day,setDay,addPlace,back}:{trip:Trip;items:Itinerary[];day:number;setDay:(n:number)=>void;addPlace:()=>void;back:()=>void}){
  const now=useMinuteClock();
  const tripDay=tripDayAt(trip,now);
  useEffect(()=>setDay(tripDay!==null&&tripDay>trip.total_days?trip.total_days:tripDay!==null&&tripDay>=1?tripDay:1),[trip.id,trip.total_days,tripDay,setDay]);
  const dayItems=items.filter(i=>i.day_number===day).sort((a,b)=>(a.start_time||"99:99").localeCompare(b.start_time||"99:99"));
  const slots={morning:"เช้า",afternoon:"บ่าย",evening:"เย็น"};
  const baseDate=localDate(trip.outbound_departure_at,trip.start_date);
  const activeDateLabel=tripDayLabel(baseDate,day);
  const nowMinutes=now.getHours()*60+now.getMinutes();
  const currentIndex=tripDay===day?dayItems.reduce((found,item,index)=>{const start=timeInMinutes(item.start_time);return start!==null&&start<=nowMinutes?index:found},-1):-1;
  return <div className="screen timeline-screen"><TripHeader trip={trip} back={back}/><div className="day-strip">{Array.from({length:trip.total_days},(_,i)=>i+1).map(n=>{const date=new Date(`${baseDate}T00:00:00`);date.setDate(date.getDate()+n-1);const isToday=tripDay===n;const isPast=tripDay!==null&&tripDay>n;return <button key={n} className={`day-pill ${day===n?"active":""} ${isToday?"today":""} ${isPast?"past-day":""}`} onClick={()=>setDay(n)}><small>DAY</small><strong>{n}</strong><small>{isToday?"วันนี้":date.toLocaleDateString("en",{weekday:"short"})}</small></button>})}</div><div className="section-head"><div><h2>แผนวันที่ {day}<span className="timeline-date-label">· {activeDateLabel}</span></h2><p>{tripDay===day?`เวลาปัจจุบัน ${now.toLocaleTimeString("th-TH",{hour:"2-digit",minute:"2-digit"})} · `:""}{dayItems.length} สถานที่</p></div><button className="add-btn timeline-fab" onClick={addPlace} aria-label="เพิ่มสถานที่"><Plus size={24}/></button></div>{dayItems.length===0?<EmptyState title={`Day ${day} ยังว่างอยู่`} description="เพิ่มสถานที่ เวลา และวิธีเดินทางสำหรับวันนี้" action="เพิ่มสถานที่" onClick={addPlace}/>:<div className="timeline">{dayItems.map((item,index)=>{const isCurrent=index===currentIndex;const isPast=tripDay!==null&&(tripDay>day||(tripDay===day&&currentIndex>=0&&index<currentIndex));return <div className={`timeline-stop ${isCurrent?"current-stop":""} ${isPast?"past-stop":""}`} key={item.id}><div className="event"><div className="event-dot"><MapPin size={16}/></div><article className="event-card"><div className="event-copy"><span className="event-time">{item.start_time?.slice(0,5)||"ไม่ระบุเวลา"} · {slots[item.time_slot]}</span><div className="timeline-title-row"><h3>{item.place_name}</h3></div><p><MapPin size={10}/>{item.address||"ยังไม่ได้ระบุที่อยู่"}</p></div></article></div>{index<dayItems.length-1&&<div className="transport"><TrainFront size={12}/>{item.transport_mode||"เพิ่มวิธีเดินทาง"} {item.transport_note}</div>}</div>})}</div>}</div>;
}

function CategoryDonut({categories,total}:{categories:Array<[string,number]>;total:number}){
  const t=useT();
  const [activeIndex,setActiveIndex]=useState<number|null>(categories.length?0:null);
  const colors=["#ff4f0a","#ff9f2d","#ffcc4d","#34c759","#0a84ff","#8e5cff","#ff5c8a"];
  const segments=categories.reduce((result,[category,amount],index)=>{const percent=total?amount/total*100:0;return {cursor:result.cursor+percent,items:[...result.items,{category,amount,index,percent,offset:result.cursor,color:colors[index%colors.length]}]}},{cursor:0,items:[] as Array<{category:string;amount:number;index:number;percent:number;offset:number;color:string}>}).items;
  const selectedIndex=segments.length?Math.min(activeIndex??0,segments.length-1):null;
  const active=selectedIndex===null?null:segments[selectedIndex]||null;
  const money=(amount:number)=>amount.toLocaleString("en-US",{minimumFractionDigits:amount%1?2:0,maximumFractionDigits:2});
  return <section className="budget-donut-summary"><div className="expense-total-banner"><span>{t("รวมค่าใช้จ่าย")}</span><strong>฿{money(total)}</strong><small>{t("สัดส่วนค่าใช้จ่ายตามประเภท")}</small></div><div className="donut-layout"><div className="donut-stage"><svg className="interactive-donut" viewBox="0 0 160 160" role="group" aria-label={t("สัดส่วนค่าใช้จ่ายตามประเภท")}><circle className="donut-track" cx="80" cy="80" r="54" pathLength="100"/>{segments.map(segment=><circle key={segment.category} className={`donut-segment ${selectedIndex===segment.index?"active":""}`} cx="80" cy="80" r="54" pathLength="100" fill="none" stroke={segment.color} strokeWidth="28" strokeDasharray={`${segment.percent} ${100-segment.percent}`} strokeDashoffset={-segment.offset} transform="rotate(-90 80 80)" role="button" tabIndex={0} aria-label={`${t(segment.category)} ฿${money(segment.amount)} ${segment.percent.toFixed(1)}%`} aria-pressed={selectedIndex===segment.index} onMouseEnter={()=>setActiveIndex(segment.index)} onFocus={()=>setActiveIndex(segment.index)} onClick={()=>setActiveIndex(segment.index)} onKeyDown={event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();setActiveIndex(segment.index)}}}><title>{t(segment.category)} · ฿{money(segment.amount)} · {segment.percent.toFixed(1)}%</title></circle>)}</svg><div className="donut-tooltip" role="status" aria-live="polite">{active?<><i style={{background:active.color}}/><span>{t(active.category)}</span><strong>฿{money(active.amount)}</strong><small>{active.percent.toFixed(1)}%</small></>:<><span>{t("ยังไม่มีค่าใช้จ่าย")}</span><strong>฿0</strong></>}</div></div><div className="donut-legend">{segments.length?segments.map(segment=><button type="button" key={segment.category} className={selectedIndex===segment.index?"active":""} onMouseEnter={()=>setActiveIndex(segment.index)} onFocus={()=>setActiveIndex(segment.index)} onClick={()=>setActiveIndex(segment.index)} aria-pressed={selectedIndex===segment.index}><i style={{background:segment.color}}/><span><b>{t(segment.category)}</b><small>{segment.percent.toFixed(1)}%</small></span><strong>฿{money(segment.amount)}</strong></button>):<div className="donut-empty"><span>{t("ยังไม่มีค่าใช้จ่าย")}</span><strong>฿0</strong></div>}</div></div></section>;
}

export function LegacyPlanExpensesContent({trip,items,openCost}:{trip:Trip;items:Itinerary[];openCost:(item?:Itinerary,index?:number,defaultDay?:number)=>void}){
  const t=useT();
  const total=items.reduce((sum,item)=>sum+(item.cost_items||[]).reduce((costSum,cost)=>costSum+Number(cost.value||0),0),0);
  const categories=Array.from(items.flatMap(item=>item.cost_items||[]).reduce((map,cost)=>map.set(cost.category||"อื่น ๆ",(map.get(cost.category||"อื่น ๆ")||0)+Number(cost.value||0)),new Map<string,number>())).sort((a,b)=>b[1]-a[1]);
  const availableDays=Array.from(new Set(items.map(item=>item.day_number))).sort((a,b)=>a-b);
  const firstAvailableDay=availableDays[0];
  return <div className="plan-expenses"><div className="toolbar expense-toolbar"><div><h2 style={{margin:0,fontWeight:500}}>{t("สรุปค่าใช้จ่ายจากแพลน")}</h2><p className="page-sub" style={{margin:0}}>{t("ยอดรวมแปลงเป็นเงินบาทด้วยเรตของวันที่บันทึก")}</p></div><button type="button" className="primary-btn expense-add-btn" disabled={!firstAvailableDay} title={t(firstAvailableDay?"เพิ่มค่าใช้จ่าย":"ต้องเพิ่ม Timeline ก่อน")} onClick={()=>firstAvailableDay&&openCost(undefined,undefined,firstAvailableDay)}><Plus size={15}/>{t("เพิ่มค่าใช้จ่าย")}</button></div><CategoryDonut categories={categories} total={total}/><div className="expense-days">{Array.from({length:trip.total_days},(_,index)=>index+1).map(dayNumber=>{const dayItems=items.filter(item=>item.day_number===dayNumber).sort((a,b)=>(a.start_time||"99:99").localeCompare(b.start_time||"99:99"));const dayTotal=dayItems.reduce((sum,item)=>sum+(item.cost_items||[]).reduce((costSum,cost)=>costSum+Number(cost.value||0),0),0);const count=dayItems.reduce((sum,item)=>sum+(item.cost_items||[]).length,0);return <section className={`expense-day-card ${dayItems.length?"":"without-timeline"}`} key={dayNumber}><div className="expense-day-head"><div><span>DAY {dayNumber}</span><small>{t(`${count} รายการ`)}</small></div><div className="expense-day-actions"><strong>฿{dayTotal.toLocaleString()}</strong><button type="button" disabled={!dayItems.length} title={t(dayItems.length?`เพิ่มค่าใช้จ่าย Day ${dayNumber}`:"วันนี้ยังไม่มี Timeline")} aria-label={t(dayItems.length?`เพิ่มค่าใช้จ่าย Day ${dayNumber}`:`Day ${dayNumber} ยังไม่มี Timeline`)} onClick={()=>dayItems.length&&openCost(undefined,undefined,dayNumber)}><Plus size={14}/></button></div></div>{count===0?<p className="expense-day-empty">{t(dayItems.length?"ยังไม่มีราคาที่กรอกในวันนี้":"ยังไม่มี Timeline ในวันนี้")}</p>:<div className="expense-day-list">{dayItems.flatMap(item=>(item.cost_items||[]).map((cost,index)=>{const isBaht=(cost.currency||"THB")==="THB";return <button type="button" className="expense-plan-row" key={cost.id||`${item.id}-${index}`} onClick={()=>openCost(item,index)}><div><strong>{cost.key}</strong><small>{t(cost.category||"อื่น ๆ")} · {item.start_time?.slice(0,5)||"--:--"} · {item.place_name}</small></div><span>{!isBaht&&<small>{costSourceLabel(cost)}</small>}<b>{isBaht?"":"≈ "}฿{Number(cost.value).toLocaleString()}</b></span></button>}))}</div>}</section>})}</div></div>;
}

function ExpenseSplitSummary({trip,tripTotal,shoppingTotal}:{trip:Trip;tripTotal:number;shoppingTotal:number}){
  const t=useT();const money=(value:number)=>value.toLocaleString("en-US",{minimumFractionDigits:value%1?2:0,maximumFractionDigits:2});
  return <section className="separated-expense-totals"><article><span>{t("ค่าใช้จ่ายทริป")}</span><strong>฿{money(tripTotal)}</strong><small>{t("งบหลัก")} ฿{money(Number(trip.budget_thb))}</small></article><article className="shopping-total"><span>{t("ค่า Shopping")}</span><strong>฿{money(shoppingTotal)}</strong><small>{t("งบ Shopping")} ฿{money(Number(trip.shopping_budget_thb))}</small></article></section>;
}

function PaymentMethodSummary({costs}:{costs:CostItem[]}){
  const t=useT();const money=(value:number)=>value.toLocaleString("en-US",{minimumFractionDigits:value%1?2:0,maximumFractionDigits:2});
  const rows=Array.from(costs.reduce((map,cost)=>{const method=cost.paymentMethod||"เงินสด";const current=map.get(method)||{trip:0,shopping:0};if((cost.category||"").toLowerCase()==="shopping")current.shopping+=Number(cost.value||0);else current.trip+=Number(cost.value||0);map.set(method,current);return map},new Map<string,{trip:number;shopping:number}>())).sort((a,b)=>(b[1].trip+b[1].shopping)-(a[1].trip+a[1].shopping));
  return <section className="payment-summary"><h3>{t("แยกตามช่องทางชำระ")}</h3>{rows.length?<div>{rows.map(([method,amounts])=><article key={method}><span className="payment-summary-icon"><CreditCard size={16}/></span><div><strong>{t(method)}</strong></div><div className="payment-method-totals"><span>{t("ค่าใช้จ่ายทริป")} <b>฿{money(amounts.trip)}</b></span><span>{t("ค่า Shopping")} <b>฿{money(amounts.shopping)}</b></span></div></article>)}</div>:<p>{t("ยังไม่มีข้อมูลช่องทางชำระ")}</p>}</section>;
}

function PlanExpensesContent({trip,items,openCost}:{trip:Trip;items:Itinerary[];openCost:(item?:Itinerary,index?:number,defaultDay?:number)=>void}){
  const t=useT();const allCosts=items.flatMap(item=>item.cost_items||[]);const isShopping=(cost:CostItem)=>(cost.category||"").toLowerCase()==="shopping";const tripCosts=allCosts.filter(cost=>!isShopping(cost));const shoppingCosts=allCosts.filter(isShopping);
  const tripTotal=tripCosts.reduce((sum,cost)=>sum+Number(cost.value||0),0);const shoppingTotal=shoppingCosts.reduce((sum,cost)=>sum+Number(cost.value||0),0);const categories=Array.from(tripCosts.reduce((map,cost)=>map.set(cost.category||"อื่น ๆ",(map.get(cost.category||"อื่น ๆ")||0)+Number(cost.value||0)),new Map<string,number>())).sort((a,b)=>b[1]-a[1]);const availableDays=Array.from(new Set(items.map(item=>item.day_number))).sort((a,b)=>a-b);const firstAvailableDay=availableDays[0];
  return <div className="plan-expenses">
    <div className="toolbar expense-toolbar"><div><h2 style={{margin:0,fontWeight:500}}>{t("สรุปค่าใช้จ่ายจากแพลน")}</h2><p className="page-sub" style={{margin:0}}>{t("ยอดรวมแปลงเป็นเงินบาทด้วยเรตของวันที่บันทึก")}</p></div><button type="button" className="primary-btn expense-add-btn" disabled={!firstAvailableDay} title={t(firstAvailableDay?"เพิ่มค่าใช้จ่าย":"ต้องเพิ่ม Timeline ก่อน")} onClick={()=>firstAvailableDay&&openCost(undefined,undefined,firstAvailableDay)}><Plus size={15}/>{t("เพิ่มค่าใช้จ่าย")}</button></div>
    <ExpenseSplitSummary trip={trip} tripTotal={tripTotal} shoppingTotal={shoppingTotal}/>
    <CategoryDonut categories={categories} total={tripTotal}/>
    <PaymentMethodSummary costs={allCosts}/>
    <div className="expense-days">{Array.from({length:trip.total_days},(_,index)=>index+1).map(dayNumber=>{const dayItems=items.filter(item=>item.day_number===dayNumber).sort((a,b)=>(a.start_time||"99:99").localeCompare(b.start_time||"99:99"));const dayCosts=dayItems.flatMap(item=>item.cost_items||[]);const dayTripTotal=dayCosts.filter(cost=>!isShopping(cost)).reduce((sum,cost)=>sum+Number(cost.value||0),0);const dayShoppingTotal=dayCosts.filter(isShopping).reduce((sum,cost)=>sum+Number(cost.value||0),0);const count=dayCosts.length;return <section className={`expense-day-card ${dayItems.length?"":"without-timeline"}`} key={dayNumber}><div className="expense-day-head"><div><span>DAY {dayNumber}</span><small>{t(`${count} รายการ`)}</small></div><div className="expense-day-actions"><div className="day-split-total"><span>{t("ค่าใช้จ่ายทริป")} <strong>฿{dayTripTotal.toLocaleString()}</strong></span><span>{t("ค่า Shopping")} <strong>฿{dayShoppingTotal.toLocaleString()}</strong></span></div><button type="button" disabled={!dayItems.length} title={t(dayItems.length?`เพิ่มค่าใช้จ่าย Day ${dayNumber}`:"วันนี้ยังไม่มี Timeline")} aria-label={t(dayItems.length?`เพิ่มค่าใช้จ่าย Day ${dayNumber}`:`Day ${dayNumber} ยังไม่มี Timeline`)} onClick={()=>dayItems.length&&openCost(undefined,undefined,dayNumber)}><Plus size={14}/></button></div></div>{count===0?<p className="expense-day-empty">{t(dayItems.length?"ยังไม่มีราคาที่กรอกในวันนี้":"ยังไม่มี Timeline ในวันนี้")}</p>:<div className="expense-day-list">{dayItems.flatMap(item=>(item.cost_items||[]).map((cost,costIndex)=>{const isBaht=(cost.currency||"THB")==="THB";return <button type="button" className="expense-plan-row" key={cost.id||`${item.id}-${costIndex}`} onClick={()=>openCost(item,costIndex)}><div><strong>{cost.key}</strong><small>{t(cost.category||"อื่น ๆ")} · {item.start_time?.slice(0,5)||"--:--"} · {item.place_name}</small></div><span>{!isBaht&&<small>{costSourceLabel(cost)}</small>}<b>{isBaht?"":"≈ "}฿{Number(cost.value).toLocaleString()}</b></span></button>}))}</div>}</section>})}</div>
  </div>;
}

function ExpensesScreen({trip,items,back,openCost}:{trip:Trip;items:Itinerary[];back:()=>void;openCost:(item?:Itinerary,index?:number,defaultDay?:number)=>void}){
  return <div className="screen trip-hub-screen"><div className="trip-cover-region"><TripHeader trip={trip} back={back}/></div><div className="trip-hub-body"><PlanExpensesContent trip={trip} items={items} openCost={openCost}/></div></div>;
}

function CardSheet({close,save}:{close:()=>void;save:(nickname:string,lastFour:string)=>Promise<void>}){
  const t=useT();const [saving,setSaving]=useState(false);const [error,setError]=useState("");
  useEffect(()=>{const root=document.documentElement;root.classList.add("sheet-open");return()=>root.classList.remove("sheet-open")},[]);
  async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);const nickname=String(form.get("nickname")||"").trim();const lastFour=String(form.get("lastFour")||"").trim();if(!nickname||!/^\d{4}$/.test(lastFour)){setError(t("ข้อมูลบัตรไม่ถูกต้อง"));return}setSaving(true);setError("");try{await save(nickname,lastFour);close()}catch(err){setError(err instanceof Error?err.message:t("บันทึกไม่สำเร็จ"));setSaving(false)}}
  return <div className="modal-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)close()}}><form className="modal card-sheet" onSubmit={submit}><div className="modal-head"><h2>{t("เพิ่มบัตร")}</h2><button type="button" className="icon-btn" onClick={close} aria-label={t("ยกเลิก")}><X size={18}/></button></div><div className="form-grid"><div className="field"><label>{t("ชื่อบัตร")}</label><input name="nickname" required maxLength={40} autoComplete="off" placeholder={t("เช่น KBank Platinum")}/></div><div className="field"><label>{t("เลข 4 หลักสุดท้าย")}</label><div className="card-last-four-input"><span>x-</span><input name="lastFour" required type="text" inputMode="numeric" autoComplete="off" pattern="[0-9]{4}" maxLength={4} placeholder="4323"/></div></div><p className="card-security-note">{t("บันทึกเฉพาะชื่อเรียกและเลข 4 หลักท้าย ไม่เก็บเลขบัตรเต็ม")}</p></div>{error&&<p className="login-error">{error}</p>}<div className="modal-submit-actions"><button className="primary-btn" disabled={saving}>{t(saving?"กำลังบันทึกบัตร…":"บันทึกบัตร")}</button></div></form></div>;
}

function SettingsScreen({dark,toggleTheme,lang,setLang,logout,cards,addCard,deleteCard}:{dark:boolean;toggleTheme:()=>void;lang:Lang;setLang:(l:Lang)=>void;logout:()=>void;cards:PaymentCard[];addCard:(nickname:string,lastFour:string)=>Promise<void>;deleteCard:(card:PaymentCard)=>void}){
  const t=(value:string)=>lang==="EN"?translateUiText(value):value;const [cardSheet,setCardSheet]=useState(false);
  return <div className="screen"><h1 className="page-title">{t("ตั้งค่า")}</h1><p className="page-sub">{t("ค่าของบัญชีและอุปกรณ์นี้")}</p><div className="settings-list"><article className="card"><div className="setting-row"><div className="setting-label"><span className="stat-icon">{dark?<Moon size={17}/>:<Sun size={17}/>}</span><div><strong>{t("ธีมการแสดงผล")}</strong><small>{t("สลับ Light / Dark mode")}</small></div></div><button type="button" className={`toggle ${dark?"on":""}`} onClick={toggleTheme} aria-label={t("เปลี่ยนธีม")}><span/></button></div></article><article className="card"><div className="setting-row"><div className="setting-label"><span className="stat-icon"><Languages size={17}/></span><div><strong>{t("ภาษา · Language")}</strong><small>{t("ภาษาอินเทอร์เฟซหลัก")}</small></div></div><div className="segmented"><button type="button" className={lang==="TH"?"active":""} onClick={()=>setLang("TH")} aria-pressed={lang==="TH"}>TH</button><button type="button" className={lang==="EN"?"active":""} onClick={()=>setLang("EN")} aria-pressed={lang==="EN"}>EN</button></div></div></article><article className="card payment-settings-card"><div className="section-head"><div><h2>{t("บัตรและการชำระเงิน")}</h2><p>{cards.length?`${cards.length} ${lang==="EN"?(cards.length===1?"card":"cards"):"บัตร"}`:t("ยังไม่มีบัตรที่บันทึกไว้")}</p></div><button type="button" className="text-btn card-add-btn" onClick={()=>setCardSheet(true)}><Plus size={14}/>{t("เพิ่มบัตร")}</button></div>{cards.length>0&&<div className="saved-card-list">{cards.map(card=><div className="saved-card-row" key={card.id}><span className="saved-card-icon"><CreditCard size={17}/></span><div><strong>{card.nickname}</strong><small>x-{card.last_four}</small></div><button type="button" className="saved-card-delete" onClick={()=>deleteCard(card)} aria-label={`${t("ลบบัตรนี้")} ${card.nickname}`} title={t("ลบบัตรนี้")}><Trash2 size={16}/></button></div>)}</div>}</article><article className="card logout-setting"><div className="setting-row"><div className="setting-label"><span className="stat-icon"><LogOut size={17}/></span><div><strong>{t("ออกจากระบบ")}</strong><small>{t("ออกจากบัญชีบนอุปกรณ์นี้")}</small></div></div><button type="button" className="settings-logout-btn" onClick={logout}>{t("ออกจากระบบ")}</button></div></article></div>{cardSheet&&<CardSheet close={()=>setCardSheet(false)} save={addCard}/>}</div>;
}

function ConfirmDialog({confirmation,close}:{confirmation:Confirmation;close:()=>void}){
  const t=useT();
  const [busy,setBusy]=useState(false);
  useEffect(()=>{document.documentElement.classList.add("confirm-open");return()=>document.documentElement.classList.remove("confirm-open")},[]);
  const confirm=async()=>{setBusy(true);try{await confirmation.onConfirm();close()}catch{setBusy(false)}};
  return <div className="confirm-backdrop" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget&&!busy)close()}}><div className="confirm-dialog" role="alertdialog" aria-modal="true" aria-labelledby="confirm-title"><span className="confirm-icon"><AlertTriangle size={22}/></span><h2 id="confirm-title">{t(confirmation.title)}</h2><p>{t(confirmation.description)}</p><div className="confirm-actions"><button type="button" className="confirm-cancel" onClick={close} disabled={busy}>{t("ยกเลิก")}</button><button type="button" className="confirm-delete" onClick={confirm} disabled={busy}>{t(busy?"กำลังลบ…":confirmation.confirmLabel||"ยืนยันการลบ")}</button></div></div></div>;
}

type CropSource = { file:File; image:HTMLImageElement; url:string };

function CoverImagePicker({existingUrl,onChange}:{existingUrl?:string|null;onChange:(file:File|null)=>void}){
  const inputRef=useRef<HTMLInputElement>(null);const canvasRef=useRef<HTMLCanvasElement>(null);const objectUrls=useRef<string[]>([]);
  const [source,setSource]=useState<CropSource|null>(null);const [preview,setPreview]=useState(existingUrl||"");const [cropping,setCropping]=useState(false);const [zoom,setZoom]=useState(1);const [positionX,setPositionX]=useState(0);const [positionY,setPositionY]=useState(0);const [error,setError]=useState("");
  useEffect(()=>()=>{objectUrls.current.forEach(url=>URL.revokeObjectURL(url))},[]);
  useEffect(()=>{const canvas=canvasRef.current;if(!canvas||!source)return;const context=canvas.getContext("2d");if(!context)return;const outputWidth=1600;const outputHeight=900;const imageWidth=source.image.naturalWidth;const imageHeight=source.image.naturalHeight;const scale=Math.max(outputWidth/imageWidth,outputHeight/imageHeight)*zoom;const visibleWidth=outputWidth/scale;const visibleHeight=outputHeight/scale;const centerX=imageWidth/2+(positionX/100)*(imageWidth-visibleWidth)/2;const centerY=imageHeight/2+(positionY/100)*(imageHeight-visibleHeight)/2;const sx=Math.max(0,Math.min(imageWidth-visibleWidth,centerX-visibleWidth/2));const sy=Math.max(0,Math.min(imageHeight-visibleHeight,centerY-visibleHeight/2));context.clearRect(0,0,outputWidth,outputHeight);context.drawImage(source.image,sx,sy,visibleWidth,visibleHeight,0,0,outputWidth,outputHeight)},[source,zoom,positionX,positionY]);
  function selectFile(event:React.ChangeEvent<HTMLInputElement>){const file=event.target.files?.[0];if(!file)return;setError("");if(!["image/jpeg","image/png","image/webp"].includes(file.type)){setError("รองรับเฉพาะ JPG, PNG และ WebP");return}if(file.size>8*1024*1024){setError("รูปต้องมีขนาดไม่เกิน 8 MB");return}const url=URL.createObjectURL(file);objectUrls.current.push(url);const image=new window.Image();image.onload=()=>{setSource({file,image,url});setZoom(1);setPositionX(0);setPositionY(0);setCropping(true)};image.onerror=()=>setError("ไม่สามารถอ่านไฟล์รูปนี้ได้");image.src=url;}
  async function applyCrop(){const canvas=canvasRef.current;if(!canvas||!source)return;const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,"image/jpeg",.88));if(!blob){setError("ไม่สามารถ Crop รูปได้");return}const baseName=source.file.name.replace(/\.[^.]+$/,"")||"trip-cover";const croppedFile=new File([blob],`${baseName}-cover.jpg`,{type:"image/jpeg"});const url=URL.createObjectURL(blob);objectUrls.current.push(url);setPreview(url);setCropping(false);onChange(croppedFile)}
  function cancelCrop(){setCropping(false);setSource(null);if(inputRef.current)inputRef.current.value=""}
  return <div className="cover-picker">
    {!cropping&&<label className="upload-field cover-upload"><span className="upload-preview" style={preview?{backgroundImage:`url("${preview}")`}:undefined}>{!preview&&<ImagePlus size={24}/>}</span><span><strong>{preview?"เปลี่ยนรูปหน้าปก":"เพิ่มรูปหน้าปก"}</strong><small>ระบบจะ Crop เป็นภาพแนวนอน 16:9 · JPG, PNG หรือ WebP</small></span><input ref={inputRef} type="file" accept="image/jpeg,image/png,image/webp" onChange={selectFile}/></label>}
    {cropping&&<div className="cover-cropper"><div className="crop-head"><div><strong>จัดตำแหน่งรูปหน้าปก</strong><small>ภาพที่ได้เป็นสัดส่วน 16:9</small></div><button type="button" onClick={cancelCrop}>ยกเลิก</button></div><div className="crop-canvas-wrap"><canvas ref={canvasRef} width={1600} height={900}/><span>16 : 9</span></div><div className="crop-controls"><label><span>ซูม</span><input type="range" min="1" max="2.5" step="0.01" value={zoom} onChange={event=>setZoom(Number(event.target.value))}/></label><label><span>ซ้าย–ขวา</span><input type="range" min="-100" max="100" value={positionX} onChange={event=>setPositionX(Number(event.target.value))}/></label><label><span>บน–ล่าง</span><input type="range" min="-100" max="100" value={positionY} onChange={event=>setPositionY(Number(event.target.value))}/></label></div><button type="button" className="crop-apply" onClick={applyCrop}>ใช้ภาพนี้เป็นหน้าปก</button></div>}
    {error&&<p className="cover-error">{error}</p>}
  </div>;
}

function CostSheet({modal,trip,items,cards,close,saveCost,deleteCost}:{modal:Extract<NonNullable<Modal>,{type:"cost"}>;trip:Trip;items:Itinerary[];cards:PaymentCard[];close:()=>void;saveCost:(source:Itinerary|undefined,index:number|undefined,target:Itinerary,cost:CostItem)=>Promise<void>;deleteCost:(item:Itinerary,index:number)=>Promise<void>}){
  const existing=modal.item&&modal.costIndex!==undefined?modal.item.cost_items[modal.costIndex]:undefined;
  const availableDays=Array.from(new Set(items.map(item=>item.day_number))).sort((a,b)=>a-b);
  const requestedDay=modal.item?.day_number||modal.defaultDay;
  const initialDay=requestedDay&&availableDays.includes(requestedDay)?requestedDay:availableDays[0]||1;
  const [selectedDay,setSelectedDay]=useState(initialDay);
  const dayItems=items.filter(item=>item.day_number===selectedDay).sort((a,b)=>(a.start_time||"99:99").localeCompare(b.start_time||"99:99"));
  const [targetId,setTargetId]=useState(modal.item?.id||dayItems[0]?.id||"");
  const [currency,setCurrency]=useState(existing?.currency||"THB");
  const dayDate=(day:number)=>addDays(localDate(trip.outbound_departure_at,trip.start_date),day-1);
  const [exchangeRate,setExchangeRate]=useState(String(existing?.exchangeRate??1));
  const [rateDate,setRateDate]=useState(existing?.rateDate||dayDate(initialDay));
  const [rateLoading,setRateLoading]=useState(false);const [rateEstimated,setRateEstimated]=useState(false);
  const [saving,setSaving]=useState(false);const [error,setError]=useState("");const [confirmDelete,setConfirmDelete]=useState(false);
  useEffect(()=>{const root=document.documentElement;root.classList.add("sheet-open");return()=>root.classList.remove("sheet-open")},[]);
  async function loadRate(nextCurrency:string,date:string){setCurrency(nextCurrency);setRateDate(date);if(nextCurrency==="THB"){setExchangeRate("1");setRateEstimated(false);return}setRateLoading(true);setError("");try{const response=await fetch(`/api/exchange-rate?currency=${nextCurrency}&date=${date}`);const data=await response.json();if(!response.ok)throw new Error(data.error);setExchangeRate(String(data.rate));setRateDate(data.date);setRateEstimated(Boolean(data.estimated))}catch(err){setError(err instanceof Error?err.message:"โหลดอัตราแลกเปลี่ยนไม่สำเร็จ")}finally{setRateLoading(false)}}
  async function handle(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);const target=items.find(item=>item.id===targetId);if(!target){setError("กรุณาเลือกจุดใน Timeline");return}const foreignAmount=Number(String(form.get("foreignAmount")||"0").replace(/,/g,""));const rate=Number(exchangeRate||1);if(!Number.isFinite(foreignAmount)||foreignAmount<0){setError("กรุณากรอกยอดเงินให้ถูกต้อง");return}if(!Number.isFinite(rate)||rate<=0){setError("กรุณากรอกอัตราแลกเปลี่ยนให้ถูกต้อง");return}const cost:CostItem={id:existing?.id||crypto.randomUUID(),key:String(form.get("title")||"").trim(),category:String(form.get("category")||"อื่น ๆ"),currency,foreignAmount,exchangeRate:rate,rateDate,paymentMethod:String(form.get("paymentMethod")||"เงินสด"),value:Math.round(foreignAmount*rate*100)/100};setSaving(true);setError("");try{await saveCost(modal.item,modal.costIndex,target,cost);close()}catch(err){setError(err instanceof Error?err.message:"บันทึกค่าใช้จ่ายไม่สำเร็จ");setSaving(false)}}
  const savedCardOptions=cards.map(card=>`${card.nickname} · x-${card.last_four}`);const standardMethods=["เงินสด","โอนเงิน","บัตรเครดิต","บัตรเดบิต","อื่น ๆ"];const selectedMethod=existing?.paymentMethod||"เงินสด";const paymentMethods=[...standardMethods,...savedCardOptions];if(!paymentMethods.includes(selectedMethod))paymentMethods.push(selectedMethod);
  return <div className="modal-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)close()}}><form className="modal cost-sheet" onSubmit={handle}><div className="modal-head"><div><h2>{existing?"แก้ไขค่าใช้จ่าย":"เพิ่มค่าใช้จ่าย"}</h2><p>{existing?"แก้ไขหรือย้ายรายการไปยัง Timeline อื่นได้":"เลือกรายการในแพลนที่ค่าใช้จ่ายนี้เกิดขึ้น"}</p></div><button type="button" className="icon-btn" onClick={close}><X size={18}/></button></div><div className="form-grid"><div className="form-row"><div className="field"><label>วันที่</label><select value={selectedDay} onChange={event=>{const nextDay=Number(event.target.value);const date=dayDate(nextDay);setSelectedDay(nextDay);setTargetId(items.find(item=>item.day_number===nextDay)?.id||"");void loadRate(currency,date)}}>{availableDays.map(day=><option key={day} value={day}>Day {day} · {tripDayLabel(localDate(trip.outbound_departure_at,trip.start_date),day)}</option>)}</select></div><div className="field"><label>จุดใน Timeline</label><select value={targetId} onChange={event=>setTargetId(event.target.value)} required disabled={!dayItems.length}><option value="">{dayItems.length?"เลือก Timeline":"วันนี้ยังไม่มี Timeline"}</option>{dayItems.map(item=><option key={item.id} value={item.id}>{item.start_time?.slice(0,5)||"--:--"} · {item.place_name}</option>)}</select></div></div><div className="field"><label>รายการ</label><input name="title" required defaultValue={existing?.key} placeholder="เช่น ค่าอาหารเย็น"/></div><div className="field"><label>หมวดหมู่</label><select name="category" defaultValue={existing?.category||"อาหาร"}><option>อาหาร</option><option>เดินทาง</option><option>ค่าตั๋วเครื่องบิน</option><option>ที่พัก</option><option>Shopping</option><option>กิจกรรม</option><option>ของฝาก</option><option>อื่น ๆ</option></select></div><div className="form-row money-currency-row"><div className="field"><label>ยอดเงิน</label><MoneyInput name="foreignAmount" required defaultValue={existing?.foreignAmount??existing?.value}/></div><div className="field"><label>สกุลเงิน</label><select name="currency" value={currency} onChange={event=>void loadRate(event.target.value,dayDate(selectedDay))}><option value="THB">บาท (THB)</option><option value="CNY">หยวน (CNY)</option><option value="JPY">เยน (JPY)</option><option value="USD">ดอลลาร์ (USD)</option></select></div></div>{currency!=="THB"&&<p className={`exchange-rate-note ${rateLoading?"loading":""}`}>{rateLoading?"กำลังโหลดอัตราแลกเปลี่ยน…":`1 ${currency} = ${exchangeRate} THB · เรต ${rateEstimated?"ล่าสุดสำหรับวันในอนาคต":"ประจำวันที่"} ${rateDate}`}</p>}<div className="field"><label>ช่องทางชำระ</label><select name="paymentMethod" defaultValue={selectedMethod}>{paymentMethods.map(method=><option key={method}>{method}</option>)}</select></div></div>{error&&<p className="login-error">{error}</p>}<div className="modal-submit-actions"><button className="primary-btn" disabled={saving||rateLoading||!targetId}>{saving?"กำลังบันทึก…":"บันทึกค่าใช้จ่าย"}</button>{existing&&modal.item&&modal.costIndex!==undefined&&<button type="button" className="delete-record-btn" onClick={()=>setConfirmDelete(true)} disabled={saving} aria-label="ลบค่าใช้จ่าย" title="ลบค่าใช้จ่าย"><Trash2 size={18}/></button>}</div></form>{confirmDelete&&modal.item&&modal.costIndex!==undefined&&<ConfirmDialog confirmation={{title:`ลบ “${existing?.key}”?`,description:"ค่าใช้จ่ายนี้จะถูกลบออกจาก Timeline และหน้าสรุป",confirmLabel:"ลบค่าใช้จ่าย",onConfirm:async()=>{await deleteCost(modal.item!,modal.costIndex!);setConfirmDelete(false);close()}}} close={()=>setConfirmDelete(false)}/>}</div>;
}

function ModalForm({modal,trip,day,close,submit,deleteItem,deleteTrip}:{modal:Extract<NonNullable<Modal>,{type:"trip"|"place"}>;trip:Trip|null;day:number;close:()=>void;submit:(data:Record<string,unknown>)=>Promise<void>;deleteItem:(item:Itinerary)=>Promise<void>;deleteTrip:(trip:Trip)=>Promise<void>}){
  const [saving,setSaving]=useState(false);const [error,setError]=useState("");
  const [coverFile,setCoverFile]=useState<File|null>(null);
  const [pendingDelete,setPendingDelete]=useState(false);
  useEffect(()=>{const root=document.documentElement;root.classList.add("sheet-open");return()=>root.classList.remove("sheet-open")},[]);
  const initialOutboundDate=modal.type==="trip"?localDate(modal.trip?.outbound_departure_at,modal.trip?.start_date||""):"";
  const returnFallback=modal.type==="trip"&&modal.trip?addDays(modal.trip.start_date,modal.trip.total_days-1):"";
  const savedReturnDate=modal.type==="trip"?localDate(modal.trip?.return_departure_at,returnFallback):"";
  const initialReturnDate=initialOutboundDate&&savedReturnDate<=initialOutboundDate?addDays(initialOutboundDate,1):savedReturnDate;
  const [outboundDate,setOutboundDate]=useState(initialOutboundDate);const [returnDate,setReturnDate]=useState(initialReturnDate);
  const amount=(f:FormData,name:string)=>Number(String(f.get(name)||"0").replace(/,/g,""));
  async function handle(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setSaving(true);setError("");const f=new FormData(e.currentTarget);try{if(modal.type==="trip"){let coverImageUrl=modal.trip?.cover_image_url||DEFAULT_TRIP_COVER;if(coverFile){const upload=new FormData();upload.set("file",coverFile);const response=await fetch("/api/uploads",{method:"POST",body:upload});const result=await response.json();if(!response.ok)throw new Error(result.error||"อัปโหลดรูปไม่สำเร็จ");coverImageUrl=result.url}await submit({name:f.get("name"),destination:f.get("destination"),outboundDate:f.get("outboundDate"),outboundTime:f.get("outboundTime"),returnDate:f.get("returnDate"),returnTime:f.get("returnTime"),budgetThb:amount(f,"budgetThb"),shoppingBudgetThb:amount(f,"shoppingBudgetThb"),coverImageUrl})}if(modal.type==="place"){const startTime=String(f.get("startTime"));const hour=Number(startTime.slice(0,2));const timeSlot=hour<12?"morning":hour<17?"afternoon":"evening";await submit({placeName:f.get("placeName"),address:f.get("address"),transportMode:f.get("transportMode"),transportNote:f.get("transportNote"),costItems:modal.item?.cost_items||[],dayNumber:Number(f.get("dayNumber")),timeSlot,startTime})}close()}catch(err){setError(err instanceof Error?err.message:"บันทึกไม่สำเร็จ");setSaving(false)}}
  const title=modal.type==="trip"?(modal.trip?"แก้ไขทริป":"สร้างทริปใหม่"):(modal.item?"แก้ไขรายการ":"เพิ่มแผนเที่ยว");
  return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><form className="modal" onSubmit={handle}><div className="modal-head"><h2>{title}</h2><button type="button" className="icon-btn" onClick={close}><X size={18}/></button></div><div className="form-grid">
    {modal.type==="trip"&&<><CoverImagePicker existingUrl={modal.trip?.cover_image_url} onChange={setCoverFile}/><div className="field"><label>ชื่อทริป</label><input name="name" required defaultValue={modal.trip?.name}/></div><div className="field"><label>เมืองหรือประเทศปลายทาง</label><input name="destination" required defaultValue={modal.trip?.destination}/></div><div className="form-row flight-datetime-row"><div className="field"><label>วันบินขาไป</label><NativeDateTimeInput name="outboundDate" type="date" required defaultValue={initialOutboundDate} value={outboundDate} onValueChange={value=>{setOutboundDate(value);setReturnDate(value?addDays(value,1):"")}} label="วันบินขาไป"/></div><div className="field"><label>เวลาเที่ยวบินขาไป</label><NativeDateTimeInput name="outboundTime" type="time" required defaultValue={localTime(modal.trip?.outbound_departure_at)} label="เวลาเที่ยวบินขาไป"/></div></div><div className={`form-row flight-datetime-row ${outboundDate?"":"disabled-row"}`}><div className="field"><label>วันเดินทางกลับ</label><NativeDateTimeInput name="returnDate" type="date" required defaultValue={initialReturnDate} value={returnDate} onValueChange={setReturnDate} min={outboundDate?addDays(outboundDate,1):undefined} disabled={!outboundDate} label="วันเดินทางกลับ"/></div><div className="field"><label>เวลาเที่ยวบินกลับ</label><NativeDateTimeInput name="returnTime" type="time" required defaultValue={localTime(modal.trip?.return_departure_at,"18:00")} disabled={!outboundDate} label="เวลาเที่ยวบินกลับ"/></div></div><div className="form-row budget-row"><div className="field"><label>งบหลัก (THB)</label><MoneyInput name="budgetThb" required defaultValue={modal.trip?.budget_thb||0}/></div><div className="field"><label>งบ Shopping แยก (THB)</label><MoneyInput name="shoppingBudgetThb" required defaultValue={modal.trip?.shopping_budget_thb||0}/></div></div></>}
    {modal.type==="place"&&<><div className="form-row"><div className="field"><label>วัน</label><select name="dayNumber" required defaultValue={modal.item?.day_number||day}>{Array.from({length:trip?.total_days||1},(_,index)=>index+1).map(number=><option key={number} value={number}>Day {number}</option>)}</select></div><div className="field"><label>เวลา</label><NativeDateTimeInput name="startTime" type="time" required defaultValue={modal.item?.start_time?.slice(0,5)||"09:00"} label="เวลาเริ่มรายการ"/></div></div><p className="field-hint">เปลี่ยนแผนได้ทุกเมื่อ ระบบจะย้ายรายการไปยังวันที่เลือกและเรียงตามเวลาให้อัตโนมัติ</p><div className="field"><label>ชื่อรายการ</label><input name="placeName" required defaultValue={modal.item?.place_name}/></div><div className="field"><label>สถานที่ / ที่อยู่</label><input name="address" defaultValue={modal.item?.address||""}/></div><div className="field"><label>วิธีเดินทางไปจุดถัดไป</label><select name="transportMode" defaultValue={modal.item?.transport_mode||"เดิน"}><option>เดิน</option><option>รถไฟ</option><option>รถยนต์</option><option>รถบัส</option><option>แท็กซี่</option><option>เครื่องบิน</option><option>เรือ</option></select></div><div className="field"><label>รายละเอียด</label><textarea name="transportNote" rows={3} defaultValue={modal.item?.transport_note||""} placeholder="รายละเอียดร้าน การเดินทาง หรือสิ่งที่ต้องจำ"/></div></>}
  </div>{error&&<p className="login-error">{error}</p>}<div className="modal-submit-actions"><button className="primary-btn" disabled={saving}>{saving?"กำลังบันทึก…":"บันทึก"}</button>{((modal.type==="place"&&modal.item)||(modal.type==="trip"&&modal.trip))&&<button type="button" className="delete-record-btn" onClick={()=>setPendingDelete(true)} disabled={saving} aria-label={modal.type==="trip"?"ลบทริป":"ลบรายการ"} title={modal.type==="trip"?"ลบทริป":"ลบรายการ"}><Trash2 size={18}/></button>}</div></form>{pendingDelete&&modal.type==="place"&&modal.item&&<ConfirmDialog confirmation={{title:`ลบ “${modal.item.place_name}”?`,description:"รายการนี้ รวมถึงรายละเอียดและราคาที่บันทึกไว้จะถูกลบออกจาก Timeline",confirmLabel:"ลบรายการ",onConfirm:async()=>{await deleteItem(modal.item!);setPendingDelete(false);close()}}} close={()=>setPendingDelete(false)}/>} {pendingDelete&&modal.type==="trip"&&modal.trip&&<ConfirmDialog confirmation={{title:`ลบทริป “${modal.trip.name}”?`,description:"แผนเที่ยว ค่าใช้จ่าย และข้อมูลทั้งหมดในทริปนี้จะถูกลบถาวร",confirmLabel:"ลบทริป",onConfirm:async()=>{await deleteTrip(modal.trip!);setPendingDelete(false);close()}}} close={()=>setPendingDelete(false)}/>}</div>;
}

export function BNTripApp({authenticated=false,page="dashboard",tripId}:{authenticated?:boolean;page?:Screen;tripId?:string}){
  const router=useRouter();const [dark,setDark]=useState(false);const [lang,setLang]=useState<Lang>("TH");const [trips,setTrips]=useState<Trip[]>(()=>tripListCache||[]);const [selected,setSelected]=useState<Trip|null>(()=>tripId?tripListCache?.find(trip=>trip.id===tripId)||null:null);const [itineraries,setItineraries]=useState<Itinerary[]>(()=>tripId?itineraryCache.get(tripId)||[]:[]);const [cards,setCards]=useState<PaymentCard[]>([]);const [modal,setModal]=useState<Modal>(null);const [confirmation,setConfirmation]=useState<Confirmation|null>(null);const [toast,setToast]=useState("");const [loading,setLoading]=useState(page!=="settings"&&!tripListCache);const [activeDay,setActiveDay]=useState(1);
  useEffect(()=>{const frame=requestAnimationFrame(()=>{setDark(document.documentElement.classList.contains("dark"));const saved=localStorage.getItem("bn-lang") as Lang|null;if(saved){activeLang=saved;setLang(saved)}});return()=>cancelAnimationFrame(frame)},[]);
  useEffect(()=>{activeLang=lang;document.documentElement.lang=lang==="EN"?"en":"th"},[lang]);
  useEffect(()=>{if(!authenticated)return;let active=true;fetch("/api/cards").then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.error);if(active)setCards(Array.isArray(data)?data:[])}).catch(()=>{if(active)setCards([])});return()=>{active=false}},[authenticated]);
  useEffect(()=>{if(!authenticated||page==="settings")return;const cacheMiss=!tripListCache||(Boolean(tripId)&&!tripListCache.some(trip=>trip.id===tripId));const shouldRefresh=cacheMiss||(page==="dashboard"&&tripListCacheStale);if(!shouldRefresh)return;let active=true;fetchTripList().then(rows=>{if(!active)return;setTrips(rows);setSelected(tripId?rows.find(trip=>trip.id===tripId)||null:null);setLoading(false)}).catch(()=>{if(active)setLoading(false)});return()=>{active=false}},[authenticated,page,tripId]);
  useEffect(()=>{if(!selected||itineraryCache.has(selected.id))return;let active=true;void (async()=>{const response=await fetch(`/api/trips/${selected.id}/itineraries`);const data=await response.json();const rows:Itinerary[]=Array.isArray(data)?data:[];const rateCache=new Map<string,Promise<{rate:number;date:string}>>();const enriched=await Promise.all(rows.map(async item=>{let changed=false;const plannedDate=addDays(localDate(selected.outbound_departure_at,selected.start_date),item.day_number-1);const costItems=await Promise.all((item.cost_items||[]).map(async cost=>{const currency=cost.currency||"THB";if(currency==="THB"||cost.rateDate)return cost;const cacheKey=`${currency}-${plannedDate}`;if(!rateCache.has(cacheKey))rateCache.set(cacheKey,fetch(`/api/exchange-rate?currency=${currency}&date=${plannedDate}`).then(async rateResponse=>{const rateData=await rateResponse.json();if(!rateResponse.ok)throw new Error(rateData.error);return rateData}));try{const rateData=await rateCache.get(cacheKey)!;const foreignAmount=Number(cost.foreignAmount??cost.value);changed=true;return {...cost,foreignAmount,exchangeRate:Number(rateData.rate),rateDate:rateData.date,value:Math.round(foreignAmount*Number(rateData.rate)*100)/100}}catch{return cost}}));if(!changed)return item;const startTime=item.start_time?.slice(0,5)||"09:00";const hour=Number(startTime.slice(0,2));const patched=await fetch(`/api/itineraries/${item.id}`,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({dayNumber:item.day_number,timeSlot:hour<12?"morning":hour<17?"afternoon":"evening",startTime,placeName:item.place_name,address:item.address||"",transportMode:item.transport_mode||undefined,transportNote:item.transport_note||"",costItems})});return patched.ok?await patched.json():{...item,cost_items:costItems}}));itineraryCache.set(selected.id,enriched);if(active)setItineraries(enriched)})().catch(()=>{if(active)setItineraries([])});return()=>{active=false}},[selected]);
  if(!authenticated)return <LanguageContext.Provider value={lang}><LoginScreen/></LanguageContext.Provider>;
  const flash=(message:string)=>{setToast(message);setTimeout(()=>setToast(""),2400)};
  const toggleTheme=()=>{const next=!dark;setDark(next);document.documentElement.classList.toggle("dark",next);localStorage.setItem("bn-theme",next?"dark":"light");document.querySelector('meta[name="theme-color"]')?.setAttribute("content",next?"#000000":"#f2f2f7")};
  const request=async(url:string,options?:RequestInit)=>{const response=await fetch(url,options);const data=await response.json();if(!response.ok)throw new Error(data.error||"บันทึกไม่สำเร็จ");return data};
  async function saveModal(data:Record<string,unknown>){if(!modal)return;if(modal.type==="trip"){const saved=await request(modal.trip?`/api/trips/${modal.trip.id}`:"/api/trips",{method:modal.trip?"PATCH":"POST",headers:{"content-type":"application/json"},body:JSON.stringify(data)});setTrips(old=>{const next:Trip[]=modal.trip?old.map(t=>t.id===saved.id?saved:t):[saved,...old];tripListCache=next;tripListCacheStale=true;return next});if(!modal.trip)itineraryCache.set(saved.id,[]);setSelected(saved);flash(modal.trip?"แก้ไขทริปแล้ว":"สร้างทริปแล้ว เลือกสิ่งที่ต้องการจัดการได้เลย");router.push(`/trips/${saved.id}`)}if(modal.type==="place"&&selected){const editing=modal.item;const saved=await request(editing?`/api/itineraries/${editing.id}`:`/api/trips/${selected.id}/itineraries`,{method:editing?"PATCH":"POST",headers:{"content-type":"application/json"},body:JSON.stringify(data)});setItineraries(old=>{const next:Itinerary[]=(editing?old.map(item=>item.id===saved.id?saved:item):[...old,saved]).sort((a,b)=>a.day_number-b.day_number||(a.start_time||"99:99").localeCompare(b.start_time||"99:99"));itineraryCache.set(selected.id,next);return next});setActiveDay(saved.day_number);flash(editing?"อัปเดตวัน เวลา และรายละเอียดแล้ว":"เพิ่มแผนเที่ยวและเรียง Timeline แล้ว")}}
  async function removeItinerary(item:Itinerary){await request(`/api/itineraries/${item.id}`,{method:"DELETE"});setItineraries(old=>{const next=old.filter(row=>row.id!==item.id);if(selected)itineraryCache.set(selected.id,next);return next});flash("ลบรายการออกจาก Timeline แล้ว")}
  async function updateItineraryCosts(item:Itinerary,costItems:CostItem[]){const startTime=item.start_time?.slice(0,5)||"09:00";const hour=Number(startTime.slice(0,2));const timeSlot=hour<12?"morning":hour<17?"afternoon":"evening";const saved=await request(`/api/itineraries/${item.id}`,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({dayNumber:item.day_number,timeSlot,startTime,placeName:item.place_name,address:item.address||"",transportMode:item.transport_mode||undefined,transportNote:item.transport_note||"",costItems})});setItineraries(old=>{const next=old.map(row=>row.id===saved.id?saved:row);if(selected)itineraryCache.set(selected.id,next);return next});return saved as Itinerary}
  async function saveCost(source:Itinerary|undefined,index:number|undefined,target:Itinerary,cost:CostItem){if(source&&index!==undefined&&source.id!==target.id){await updateItineraryCosts(source,(source.cost_items||[]).filter((_,costIndex)=>costIndex!==index));await updateItineraryCosts(target,[...(target.cost_items||[]),cost])}else{const costs=[...(target.cost_items||[])];if(index!==undefined)costs[index]=cost;else costs.push(cost);await updateItineraryCosts(target,costs)}flash(index!==undefined?"แก้ไขค่าใช้จ่ายแล้ว":"เพิ่มค่าใช้จ่ายใน Timeline แล้ว")}
  async function deleteCost(item:Itinerary,index:number){await updateItineraryCosts(item,(item.cost_items||[]).filter((_,costIndex)=>costIndex!==index));flash("ลบค่าใช้จ่ายแล้ว")}
  async function removeTrip(trip:Trip){await request(`/api/trips/${trip.id}`,{method:"DELETE"});setTrips(old=>{const next=old.filter(t=>t.id!==trip.id);tripListCache=next;tripListCacheStale=true;return next});itineraryCache.delete(trip.id);if(selected?.id===trip.id)setSelected(null);flash("ลบทริปสำเร็จแล้ว");router.push("/")}
  async function addCard(nickname:string,lastFour:string){const saved:PaymentCard=await request("/api/cards",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({nickname,lastFour})});setCards(old=>[saved,...old]);flash("เพิ่มบัตรแล้ว")}
  async function removeCard(card:PaymentCard){await request(`/api/cards/${card.id}`,{method:"DELETE"});setCards(old=>old.filter(item=>item.id!==card.id));flash("ลบบัตรแล้ว")}
  const askDeleteCard=(card:PaymentCard)=>setConfirmation({title:`ลบ “${card.nickname} · x-${card.last_four}”?`,description:"บัตรจะถูกนำออกจากตัวเลือกช่องทางชำระ",confirmLabel:"ลบบัตรนี้",onConfirm:()=>removeCard(card)});
  const askDeleteTrip=(trip:Trip)=>setConfirmation({title:`ลบทริป “${trip.name}”?`,description:"แผนเที่ยว ค่าใช้จ่าย และข้อมูลทั้งหมดในทริปนี้จะถูกลบถาวร",confirmLabel:"ลบทริป",onConfirm:()=>removeTrip(trip)});
  const selectTrip=(trip:Trip)=>router.push(`/trips/${trip.id}`);
  const logout=async()=>{await fetch("/api/auth/logout",{method:"POST"});tripListCache=null;tripListCacheStale=false;itineraryCache.clear();location.href="/"};
  const openCost=(item?:Itinerary,index?:number,defaultDay?:number)=>setModal({type:"cost",item,costIndex:index,defaultDay});
  const content=loading?<div className="card">กำลังโหลดข้อมูล…</div>:page==="dashboard"?<Dashboard trips={trips} selectTrip={selectTrip} createTrip={()=>setModal({type:"trip"})} editTrip={t=>setModal({type:"trip",trip:t})} deleteTrip={askDeleteTrip}/>:page==="trip"&&selected?<TripHub trip={selected} items={itineraries} day={activeDay} setDay={setActiveDay} back={()=>router.push("/")} editTrip={()=>setModal({type:"trip",trip:selected})} addPlace={day=>{setActiveDay(day);setModal({type:"place"})}} editPlace={item=>{setActiveDay(item.day_number);setModal({type:"place",item})}} openCost={openCost}/>:page==="timeline"&&selected?<TimelineScreen trip={selected} items={itineraries} day={activeDay} setDay={setActiveDay} addPlace={()=>setModal({type:"place"})} back={()=>router.push(`/trips/${selected.id}`)}/>:page==="expenses"&&selected?<ExpensesScreen trip={selected} items={itineraries} back={()=>router.push(`/trips/${selected.id}`)} openCost={openCost}/>:page==="settings"?<SettingsScreen dark={dark} toggleTheme={toggleTheme} lang={lang} setLang={value=>{activeLang=value;setLang(value);localStorage.setItem("bn-lang",value)}} logout={logout} cards={cards} addCard={addCard} deleteCard={askDeleteCard}/>:<EmptyState title="ไม่พบทริปนี้" description="ทริปอาจถูกลบหรือไม่ได้อยู่ในบัญชีนี้" action="กลับไปเลือกทริป" onClick={()=>router.push("/")}/>;
  return <LanguageContext.Provider value={lang}><div className={`app-shell flow-shell ${page==="trip"||page==="expenses"?"trip-page-shell":""}`}>{toast&&<div className="toast toast-success" role="status"><CheckCircle2 size={17}/>{lang==="EN"?translateUiText(toast):toast}</div>}<main><header className="mobile-head flow-header"><Brand/><nav className="mobile-actions" aria-label={lang==="EN"?"Main menu":"เมนูหลัก"}>{page!=="dashboard"&&<button className="icon-btn" onClick={()=>router.push("/")} aria-label={lang==="EN"?"Home":"หน้าแรก"} title={lang==="EN"?"Home":"หน้าแรก"}><House size={18}/></button>}<button className={`icon-btn ${page==="settings"?"active":""}`} onClick={()=>router.push("/settings")} aria-label={lang==="EN"?"Settings":"ตั้งค่า"} title={lang==="EN"?"Settings":"ตั้งค่า"}><Settings2 size={18}/></button></nav></header>{content}</main>{modal&&(modal.type==="cost"?(selected?<CostSheet modal={modal} trip={selected} items={itineraries} cards={cards} close={()=>setModal(null)} saveCost={saveCost} deleteCost={deleteCost}/>:null):<ModalForm modal={modal} trip={selected} day={activeDay} close={()=>setModal(null)} submit={saveModal} deleteItem={removeItinerary} deleteTrip={removeTrip}/>)} {confirmation&&<ConfirmDialog confirmation={confirmation} close={()=>setConfirmation(null)}/>}</div></LanguageContext.Provider>;
}
